package content

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"math"
	"slices"
	"strings"
	"time"
)

// library_topics.json is the Questions library: the parent topic atlas with
// one entry per thing parents wonder about, from planning to age 9. It is
// generated by scripts/import-atlas.py from the research atlas; do not edit it
// by hand, rerun the script. Every topic cites pages that were opened on their
// checkedAt date and carries an evidence label, so a theory (Freud's stages,
// the "crisis of 3") or a folk belief never reads as medical advice.
// library_test.go checks the file.
//
//go:embed library_topics.json
var libraryJSON []byte

// Evidence labels, strongest first.
var EvidenceLabels = []string{"guideline", "research", "contested", "theory", "folk"}

// LibraryTopic is one topic of the library.
type LibraryTopic struct {
	ID, Title, Category, Evidence, EvidenceNote string
	Questions                                   []string
	WhatToKnow, AskClinicianIf                  string
	WhatToDo                                    []LibraryStep
	Sources                                     []Source
	Related                                     []string
	Urgent                                      bool
	// From and To are the age span in months from birth; pregnancy weeks are
	// negative (week 40 is 0).
	From, To float64
	// Ages is the span as a parent reads it: "Weeks 24 to 28", "1 to 3 years".
	Ages string
}

type LibraryStep struct{ When, Action string }

type atlasAge struct {
	Unit  string  `json:"unit"`
	Value float64 `json:"value"`
}

type atlasTopic struct {
	ID              string                          `json:"id"`
	Title           string                          `json:"title"`
	ParentQuestions []string                        `json:"parentQuestions"`
	Category        string                          `json:"category"`
	AgeStart        atlasAge                        `json:"ageStart"`
	AgeEnd          atlasAge                        `json:"ageEnd"`
	WhatToKnow      string                          `json:"whatToKnow"`
	WhatToDo        []struct{ When, Action string } `json:"whatToDo"`
	SeeClinicianIf  string                          `json:"seeClinicianIf"`
	Evidence        string                          `json:"evidence"`
	EvidenceNote    string                          `json:"evidenceNote"`
	Sources         []struct {
		Title     string `json:"title"`
		URL       string `json:"url"`
		CheckedAt string `json:"checkedAt"`
	} `json:"sources"`
	Related []string `json:"related"`
	Urgent  bool     `json:"urgent"`
}

var library, libraryByID = mustLoadLibrary()

func mustLoadLibrary() ([]LibraryTopic, map[string]LibraryTopic) {
	var raw []atlasTopic
	if err := json.Unmarshal(libraryJSON, &raw); err != nil {
		panic(fmt.Sprintf("library_topics.json: %v", err))
	}
	out := make([]LibraryTopic, 0, len(raw))
	byID := make(map[string]LibraryTopic, len(raw))
	for _, r := range raw {
		t := LibraryTopic{
			ID: r.ID, Title: r.Title, Category: r.Category, Evidence: r.Evidence, EvidenceNote: r.EvidenceNote,
			Questions: r.ParentQuestions, WhatToKnow: r.WhatToKnow, AskClinicianIf: r.SeeClinicianIf,
			Related: r.Related, Urgent: r.Urgent,
			From: ageMonths(r.AgeStart), To: ageMonths(r.AgeEnd), Ages: agesLabel(r.AgeStart, r.AgeEnd),
		}
		for _, s := range r.WhatToDo {
			t.WhatToDo = append(t.WhatToDo, LibraryStep{When: s.When, Action: s.Action})
		}
		for _, s := range r.Sources {
			at, err := time.Parse(time.DateOnly, s.CheckedAt)
			if err != nil {
				panic(fmt.Sprintf("library topic %s: checkedAt %q", r.ID, s.CheckedAt))
			}
			t.Sources = append(t.Sources, Source{Title: s.Title, URL: s.URL, CheckedAt: at})
		}
		out = append(out, t)
		byID[t.ID] = t
	}
	return out, byID
}

// weeksPerMonth turns gestational weeks into months before birth.
const weeksPerMonth = 4.345

func ageMonths(a atlasAge) float64 {
	switch a.Unit {
	case "pregnancyWeek":
		return (a.Value - 40) / weeksPerMonth
	case "year":
		return a.Value * 12
	default:
		return a.Value
	}
}

func agesLabel(from, to atlasAge) string {
	n := func(v float64) string { return strings.TrimSuffix(fmt.Sprintf("%.1f", v), ".0") }
	unit := func(a atlasAge, v float64) string {
		switch a.Unit {
		case "pregnancyWeek":
			return "week " + n(v) + " of pregnancy"
		case "year":
			if v == 1 {
				return "1 year"
			}
			return n(v) + " years"
		default:
			if v == 1 {
				return "1 month"
			}
			return n(v) + " months"
		}
	}
	switch {
	case from.Unit == "pregnancyWeek" && from.Value < 0 && to.Unit == "pregnancyWeek" && to.Value <= 0:
		return "Before pregnancy"
	case from.Unit == "pregnancyWeek" && from.Value < 0:
		return "Before pregnancy to " + unit(to, to.Value)
	case from.Unit == "pregnancyWeek" && to.Unit == "pregnancyWeek":
		if from.Value == to.Value {
			return "Week " + n(from.Value)
		}
		return "Weeks " + n(from.Value) + " to " + n(to.Value)
	case from.Unit == "pregnancyWeek":
		return "Week " + n(from.Value) + " to " + unit(to, to.Value)
	case from.Value == 0 && from.Unit == to.Unit:
		return "Birth to " + unit(to, to.Value)
	case from.Value == 0:
		return "Birth to " + unit(to, to.Value)
	case from.Unit == to.Unit:
		return n(from.Value) + " to " + unit(to, to.Value)
	default:
		return unit(from, from.Value) + " to " + unit(to, to.Value)
	}
}

// SoonMonths is how far ahead "coming up" looks.
const SoonMonths = 3

// LibraryPosition is where the family is on the library's age line, in months
// from birth, and how to say it.
func LibraryPosition(s State) (months float64, label string) {
	switch {
	case s.Stage == "pregnancy" && s.HasWeek:
		return (float64(s.Week) - 40) / weeksPerMonth, fmt.Sprintf("Week %d of pregnancy", s.Week)
	case s.Stage == "pregnancy":
		return -4, "Pregnancy"
	case s.Stage == "planning" || s.Stage == "trying":
		// About two months before conception (atlas week -8): the folic acid,
		// vaccines and check-up topics are all open then.
		return (-8 - 40) / weeksPerMonth, "Getting ready for a baby"
	case s.HasChild:
		m := s.AgeMonths
		switch {
		case m < 1:
			return 0.5, "The first weeks"
		case m < 24:
			if m == 1 {
				return 1, "1 month old"
			}
			return float64(m), fmt.Sprintf("%d months old", m)
		default:
			return float64(m), fmt.Sprintf("%d years old", m/12)
		}
	default:
		return 0.5, "The first weeks"
	}
}

// LibraryEntry is a topic placed against the family's position.
type LibraryEntry struct {
	LibraryTopic
	Now, Soon bool
}

// Library returns every topic, the family's now first (the narrowest span,
// so the most specific to this moment, on top), then what is coming up within
// SoonMonths (soonest first), then the rest in age order.
func Library(s State) ([]LibraryEntry, string) {
	at, label := LibraryPosition(s)
	out := make([]LibraryEntry, 0, len(library))
	for _, t := range library {
		e := LibraryEntry{LibraryTopic: t}
		e.Now = t.From <= at && at <= t.To
		e.Soon = !e.Now && t.From > at && t.From <= at+SoonMonths
		out = append(out, e)
	}
	rank := func(e LibraryEntry) int {
		switch {
		case e.Now:
			return 0
		case e.Soon:
			return 1
		}
		return 2
	}
	slices.SortStableFunc(out, func(a, b LibraryEntry) int {
		if ra, rb := rank(a), rank(b); ra != rb {
			return ra - rb
		}
		var ka, kb float64
		switch rank(a) {
		case 0:
			ka, kb = a.To-a.From, b.To-b.From
		default:
			ka, kb = a.From, b.From
		}
		if ka != kb {
			return int(math.Copysign(1, ka-kb))
		}
		return strings.Compare(a.ID, b.ID)
	})
	return out, label
}

// LibraryTopicByID returns one topic.
func LibraryTopicByID(id string) (LibraryTopic, bool) {
	t, ok := libraryByID[id]
	return t, ok
}
